{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const c of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(c)) fail(`error: line ${n}: invalid candidate name ${c}`)
      if (known.has(c)) fail(`error: line ${n}: candidate ${c} is declared twice`)
      known.add(c)
      names.push(c)
    }
  } else if (w[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const c of w.slice(2)) {
      if (!known.has(c)) fail(`error: line ${n}: unknown candidate ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is repeated`)
      seen.add(c)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = []
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const sorted = [...counts.keys()].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    if (d !== 0n) return d > 0n ? 1 : -1
    return a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${roundNo}: ${sorted.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = sorted.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...counts.keys()].filter((c) => counts.get(c) === min)
  for (let r = 0; tied.length > 1 && r < history.length; ) {
    const vs = tied.map((c) => history[r].get(c))
    let lo = vs[0]
    let same = true
    for (const v of vs) { if (v !== vs[0]) same = false; if (v < lo) lo = v }
    if (same) { r++; continue }
    tied = tied.filter((c) => history[r].get(c) === lo)
    r = 0
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + result + '\n')
else process.stdout.write(`rounds ${roundNo}\n${result}\n`)
EOF
